import {esc,loadArchive,comparisonSet,compareURL,objectURL,hasFeature,featureNames,cropOverride,viewLabel,featureValues,photoCredit} from './study-data.js';
import {Magnifier} from './magnifier.js';
const root=document.querySelector('#compare-root');
try{
 const {data,regions}=await loadArchive(),query=new URLSearchParams(location.search),id=query.get('id'),key=query.get('by')||'motifs',value=query.get('value');
 const set=comparisonSet(data,regions,id,key,value);if(!set)throw new Error('这组比对条件无效，请从器物详情重新选择。');
 const a=set.current,whole=['colors','materialGroup'].includes(key),title=value==='花卉'?'花卉 / 植物':value;
 document.title=title+' · 器物比对';document.querySelector('#back-object').href=objectURL(id);
 document.body.dataset.dimension=key;document.body.dataset.count=set.count;document.body.dataset.pinned=id;
 const options=Object.entries(featureNames).flatMap(([dimension,label])=>{const values=featureValues(a,dimension);if(dimension==='motifs'&&hasFeature(a,dimension,'鸟类'))values.unshift('鸟类');return values.filter(Boolean).map(v=>({dimension,value:v,label:label+' · '+v}))});
 function card(item,pinned=false){const r=set.region(item);return `<article class="comparison-card ${pinned?'pinned-card':''}" data-object="${esc(item.id)}"><div class="card-heading"><span>${pinned?'固定参照':'对照器物'}</span>${pinned?'<b>◈</b>':`<a class="pin-link" href="${compareURL(item.id,key,value)}" aria-label="将${esc(item.title)}固定为参照">固定到左侧</a>`}</div><div class="comparison-image ${whole?'whole-image':'detail-image'}" data-compare-image="${esc(item.id)}"></div><div class="comparison-caption"><span class="annotation-kind">${whole?'整件观察':viewLabel(r)}</span><h2><a href="${objectURL(item.id)}">${esc(item.title)} ↗</a></h2><p class="comparison-meta">${esc(item.period)}<span> / </span>${esc(item.city)}</p>${whole?`<div class="compare-swatches">${item.palette.map(c=>`<i title="${esc(c.name)} ${c.hex}" style="background:${c.hex}"></i>`).join('')}</div><p>${esc(item.material)} · ${esc(item.materialGroup)}</p>`:`<h3>${esc(r.label)}</h3><p class="region-description">${esc(r.note)}</p>`}<a class="source-mini" href="${esc(item.source)}" target="_blank" rel="noopener noreferrer">馆方资料 ↗</a>${photoCredit(item)}</div></article>`}
 root.innerHTML=`<section class="compare-intro"><div><p class="eyebrow">并置比较 / SIDE BY SIDE</p><h1>${esc(title)}<span>${featureNames[key]}比对</span></h1><p><b>${set.count}</b> 件${whole?'整器':'对应细节'} · 左侧固定当前器物，向右展开其余 ${set.others.length} 件。</p></div><label class="compare-select">换一个观察角度<select aria-label="切换比对特征">${options.map(o=>`<option value="${esc(compareURL(id,o.dimension,o.value))}" ${o.dimension===key&&o.value===value?'selected':''}>${esc(o.label)}</option>`).join('')}</select></label></section><div class="compare-tools"><p>${whole?'保留整器与色板，比较整体观感。':'每个窗口可独立拖动、放大；以实际照片局部观察。'}</p><div><button data-scroll="previous" aria-label="上一件对照器物">←</button><span id="compare-position" aria-live="polite"></span><button data-scroll="next" aria-label="下一件对照器物">→</button></div></div><section class="comparison-workspace" aria-label="固定参照与横向对照"><div class="comparison-reference">${card(a,true)}</div><div class="comparison-strip" tabindex="0" aria-label="其他器物，左右滚动比对">${set.others.map(item=>card(item)).join('')||'<div class="no-peers"><h2>这条线索暂时只有这一件</h2><p>可以切换其他纹样、色彩或材质继续比较。</p></div>'}</div></section><footer class="compare-footnote"><span>图像按观察区域适配窗口，不代表器物实物尺寸。</span><a href="${objectURL(id)}">返回 ${esc(a.title)} ↗</a></footer>`;
 const byId=new Map(data.map(item=>[item.id,item]));
 const observer=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){const host=entry.target,item=byId.get(host.dataset.compareImage),region=set.region(item);new Magnifier(host,{src:item.displayImage||item.image,rect:whole?[0,0,1,1]:cropOverride(item.id,region),label:item.title+' '+region.label});observer.unobserve(host)}},{rootMargin:'350px'});
 root.querySelectorAll('[data-compare-image]').forEach(host=>observer.observe(host));
 root.querySelector('select').onchange=e=>location.assign(e.target.value);
 const strip=root.querySelector('.comparison-strip');const step=()=>(strip.querySelector('.comparison-card')?.getBoundingClientRect().width||232)+(parseFloat(getComputedStyle(strip).columnGap)||0);
 function progress(){const n=Math.min(set.others.length,Math.round(strip.scrollLeft/step())+1);root.querySelector('#compare-position').textContent=set.others.length?`${String(n).padStart(2,'0')} / ${String(set.others.length).padStart(2,'0')}`:'0 / 0';root.querySelector('[data-scroll=previous]').disabled=strip.scrollLeft<2;root.querySelector('[data-scroll=next]').disabled=strip.scrollLeft>=strip.scrollWidth-strip.clientWidth-2;document.body.dataset.position=n}
 const travel=direction=>strip.scrollBy({left:direction*step(),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
 root.addEventListener('click',e=>{const direction=e.target.closest('[data-scroll]')?.dataset.scroll;if(direction)travel(direction==='next'?1:-1)});
 strip.addEventListener('keydown',e=>{if(e.target!==strip)return;if(['ArrowRight','ArrowLeft'].includes(e.key)){e.preventDefault();travel(e.key==='ArrowRight'?1:-1)}});
 strip.addEventListener('scroll',progress,{passive:true});new ResizeObserver(progress).observe(strip);progress();document.body.dataset.ready='true';
}catch(error){root.innerHTML=`<section class="page-error"><h1>暂时无法展开比对</h1><p>${esc(error.message)}</p><a href="index.html?return=1">返回时间轴</a></section>`;document.body.dataset.error='true';console.error(error)}
